package com.example.vehicleservice.service;
import com.example.vehicleservice.entity.*; import com.example.vehicleservice.repository.*; import com.example.vehicleservice.dto.*; import com.example.vehicleservice.mapper.ServiceRequestMapper; import com.example.vehicleservice.exception.ResourceNotFoundException;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.cache.annotation.Cacheable; import org.springframework.data.domain.*; import java.util.*; import java.math.BigDecimal;
@Service public class ServiceRequestService {
 private final ServiceRequestRepository requests; private final VehicleRepository vehicles; private final MechanicRepository mechanics; private final PartRepository parts; private final InvoiceRepository invoices; private final ServiceRequestMapper mapper;
 public ServiceRequestService(ServiceRequestRepository r,VehicleRepository v,MechanicRepository m,PartRepository p,InvoiceRepository i,ServiceRequestMapper map){requests=r;vehicles=v;mechanics=m;parts=p;invoices=i;mapper=map;}
 @Transactional public ServiceRequestResponse book(BookingRequest dto){Vehicle v=vehicles.findById(dto.vehicleId()).orElseThrow(()->new ResourceNotFoundException("Vehicle not found"));ServiceRequest r=new ServiceRequest();r.setVehicle(v);r.setDescription(dto.description());if(dto.partIds()!=null&&!dto.partIds().isEmpty())r.setParts(parts.findAllById(dto.partIds()));return mapper.toResponse(requests.save(r));}
 @Transactional public ServiceRequestResponse assignMechanic(Long requestId,Long mechanicId){ServiceRequest r=get(requestId);Mechanic m=mechanics.findById(mechanicId).orElseThrow(()->new ResourceNotFoundException("Mechanic not found"));if(!m.isAvailable())throw new IllegalArgumentException("Mechanic is not available");m.setAvailable(false);r.setMechanic(m);return mapper.toResponse(requests.save(r));}
 @Transactional public ServiceRequestResponse updateStatus(Long id,ServiceStatus status){ServiceRequest r=get(id);if(r.getStatus()==ServiceStatus.CANCELLED||r.getStatus()==ServiceStatus.COMPLETED)throw new IllegalArgumentException("Closed job status cannot be changed");r.setStatus(status);if(status==ServiceStatus.COMPLETED&&r.getMechanic()!=null)r.getMechanic().setAvailable(true);return mapper.toResponse(requests.save(r));}
 @Transactional(readOnly=true) @Cacheable(value="serviceHistory",key="#vehicleId") public List<ServiceRequestResponse> history(Long vehicleId){return requests.historyForVehicle(vehicleId).stream().map(mapper::toResponse).toList();}
 @Transactional(readOnly=true) public Page<ServiceRequestResponse> page(ServiceStatus status,int page,int size,String sortBy){return requests.findByStatus(status,PageRequest.of(page,size,Sort.by(sortBy).descending())).map(mapper::toResponse);}
 @Transactional public Invoice createInvoice(Long requestId){ServiceRequest r=get(requestId);if(r.getStatus()!=ServiceStatus.COMPLETED)throw new IllegalArgumentException("Complete the service before invoicing");if(invoices.findByServiceRequestId(requestId).isPresent())throw new IllegalArgumentException("Invoice already exists");BigDecimal total=r.getParts().stream().map(Part::getUnitPrice).reduce(BigDecimal.ZERO,BigDecimal::add);Invoice inv=new Invoice();inv.setInvoiceNumber("INV-"+System.currentTimeMillis());inv.setTotalAmount(total);inv.setServiceRequest(r);return invoices.save(inv);}
 public ServiceRequest get(Long id){return requests.findById(id).orElseThrow(()->new ResourceNotFoundException("Service request not found: "+id));}
}
